// Generated by scripts/build-assets.mjs from plugins/netrunner-agents/hooks/mascots.ts. Don't edit by hand.
// The crew: eight little pixel mascots, the colours they come in and the chrome they can wear.
// Pure functions and constants only. No Claude Code imports, so the build scripts can draw the
// exact same pixels for the README.
//
// Every mascot sits on a 64x48 grid and is built from plain <rect>s. Nothing here ever puts
// text you typed (an agent name, a task) into an SVG: only the fixed shapes and colours below.

                                                 
                                                                      

                                                         
               
              
                                                                              
             
                                                                                              
                          
              
                                                                        
                       
                                                                 
            
                                                      
                                                                         
                                                
 

export const INK = '#0B0B12'
const RED = '#FF2A6D'
const CYAN = '#00F0FF'
const LIGHT = '#E0FFFF'
const CHROME = '#B4B2A9'
const STEEL = '#5F5E5A'
const YELLOW = '#F3E600'

export const r = (x        , y        , w        , h        , fill        ) =>
  `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${fill}"/>`

