function xEye(x        , y        )         {
  return r(x, y, 4, 4, RED) + r(x + 2, y + 4, 4, 4, RED)
}

// ---------------------------------------------------------------- cosmetics

                                                         

const span = (m     ) => {
  const xs = m.eyes.map(e => e[0])
  const ys = m.eyes.map(e => e[1])
  return { x0: Math.min(...xs), x1: Math.max(...xs), y0: Math.min(...ys), y1: Math.max(...ys) }
}

/** Each cosmetic is placed from the mascot's own eyes, head and body, so it fits all eight. */
export const COSMETICS                                     = {
  none: () => '',
  visor: m => {
    const { x0, x1, y0 } = span(m)
    const left = x0 - 6
    const width = x1 + 10 - left
    return r(left, y0, width, 6, CYAN) + r(left, y0 + 2, width, 2, LIGHT) + r(left + width, y0 + 1, 4, 4, '#00808A')
  },
  mohawk: ({ top: [cx, ty] }) =>
    r(cx - 8, ty - 4, 4, 4, RED) + r(cx - 4, ty - 8, 4, 8, RED) + r(cx, ty - 12, 4, 12, RED) + r(cx + 4, ty - 8, 4, 8, RED),
  jack: ({ top: [cx, ty] }) =>
    r(cx + 12, ty - 4, 4, 4, STEEL) + r(cx + 16, ty - 8, 4, 4, YELLOW) + r(cx + 20, ty - 12, 4, 4, YELLOW) +
    r(cx + 24, ty - 12, 6, 4, YELLOW) + r(cx + 30, ty - 16, 4, 4, CHROME),
  optic: m => {
    const [ex, ey] = m.eyes[0] 
    return r(ex - 2, ey - 2, 10, m.eyeH + 4, '#2C2C2A') + r(ex, ey, 6, m.eyeH, RED) + r(ex + 8, ey + 2, 8, 2, CHROME)
  },
  mask: m => {
    const { x0, x1, y1 } = span(m)
    const y = y1 + m.eyeH - 2
    const left = x0 - 6
    const width = x1 + 10 - left
    return r(left, y, width, 8, '#444441') + r(left + 4, y + 2, 4, 4, '#888780') + r(left + width - 8, y + 2, 4, 4, '#888780') +
      r(left + width / 2 - 6, y + 4, 12, 2, YELLOW)
  },
  chromearm: ({ body: [, x1, yb] }) => r(x1, yb - 14, 10, 8, CHROME) + r(x1 + 2, yb - 12, 6, 4, STEEL) + r(x1 + 10, yb - 22, 2, 12, CYAN),
  collar: ({ body: [x0, x1, yb] }) => r(x0 - 4, yb - 8, 10, 8, YELLOW) + r(x1 - 6, yb - 8, 10, 8, YELLOW) + r(x0, yb - 4, x1 - x0, 4, YELLOW),
  circuits: ({ body: [x0, x1, yb] }) =>
    r(x0 + 4, yb - 6, 8, 1, CYAN) + r(x0 + 12, yb - 9, 1, 4, CYAN) + r(x0 + 12, yb - 9, 10, 1, CYAN) +
    r(x1 - 12, yb - 6, 8, 1, RED) + r(x1 - 4, yb - 10, 1, 5, RED),
}

// ---------------------------------------------------------------- who gets what

/** Each mascot's own look: what it wears out of the box. */
export const SIGNATURE                       = {
  daemon: { mascot: 'daemon', color: 'magenta', cosmetic: 'mohawk' },
  byte: { mascot: 'byte', color: 'cyan', cosmetic: 'none' },
  proc: { mascot: 'proc', color: 'neon', cosmetic: 'none' },
  ping: { mascot: 'ping', color: 'violet', cosmetic: 'visor' },
  node: { mascot: 'node', color: 'ember', cosmetic: 'jack' },
  shell: { mascot: 'shell', color: 'acid', cosmetic: 'none' },
  fork: { mascot: 'fork', color: 'cyan', cosmetic: 'none' },
  sentry: { mascot: 'sentry', color: 'chrome', cosmetic: 'none' },
}

/** Which agent types get which mascot out of the box. */
export const DEFAULT_LOOKS                       = {
  'general-purpose': SIGNATURE.daemon ,
  Explore: SIGNATURE.ping ,
  Plan: SIGNATURE.node ,
  fork: SIGNATURE.fork ,
}

/** The agent types each mascot turns up for, in words (for /netrunner looks and the README). */
export const ROLES                         = {
  daemon: 'general-purpose',
  ping: 'Explore',
  node: 'Plan',
  fork: 'fork',
  sentry: 'reviewers, audits, security',
  byte: 'tests, builds, lint',
  proc: 'everyone else',
  shell: 'everyone else',
}

const own =    (o                   , k        )                => (Object.hasOwn(o, k) ? o[k] : undefined)

const hash = (text        ) => {
  let h = 0
  for (const ch of text) h = (h * 31 + ch.charCodeAt(0)) >>> 0
  return h
}

/** A look for any agent type: yours if you set one, else the default, else one picked from the name (always the same one). */
export function lookFor(type        , custom                      )       {
  const chosen = own(custom, type) ?? own(DEFAULT_LOOKS, type)
  if (chosen && isLook(chosen)) return chosen
  if (/review|audit|secur/i.test(type)) return SIGNATURE.sentry 
  if (/test|qa|lint|build/i.test(type)) return SIGNATURE.byte 
  // Anyone else gets Proc or Shell, with a colour and a bit of chrome picked from their name.
  const h = hash(type)
  const colors = Object.keys(COLORS)
  const cosmetics = Object.keys(COSMETICS)
  return {
    mascot: h % 2 ? 'proc' : 'shell',
    color: colors[(h >>> 4) % colors.length] ,
    cosmetic: cosmetics[(h >>> 9) % cosmetics.length] ,
  }
}

/** True only for a look made of known names, so nothing unknown ever reaches a drawing. */
export function isLook(value         )                {
  if (!value || typeof value !== 'object') return false
  const v = value                           
  return (
    typeof v.mascot === 'string' && Object.hasOwn(MASCOTS, v.mascot) &&
    typeof v.color === 'string' && Object.hasOwn(COLORS, v.color) &&
    typeof v.cosmetic === 'string' && Object.hasOwn(COSMETICS, v.cosmetic)
  )
}

// ---------------------------------------------------------------- drawing

const cache = new Map                ()

/** The SVG for one mascot in one look and phase. Built once, then reused (about 1-2 KB each). */
export function mascotSvg(look      , phase       )         {
  const id = `${look.mascot}|${look.color}|${look.cosmetic}|${phase}`
  const hit = cache.get(id)
  if (hit) return hit

  const m = own(MASCOTS, look.mascot) ?? MASCOTS.daemon 
  const [b, s] = own(COLORS, look.color) ?? COLORS.neon 
  const wear = own(COSMETICS, look.cosmetic) ?? COSMETICS.none 
  const [x0, x1, yb] = m.body
  const topY = Math.max(4, Math.min(...m.eyes.map(e => e[1])) - 6)

  const eyes = m.drawEyes
    ? m.drawEyes(b, phase)
    : m.eyes
        .map(([x, y]) =>
          phase === 'done' ? r(x - 2, y + m.eyeH / 2, 8, 2, INK) : phase === 'failed' ? xEye(x, y) : r(x, y, 4, m.eyeH, INK),
        )
        .join('')
  // A flatlined mascot glitches: two offset ghosts behind it.
  const glitch =
    phase === 'failed'
      ? `<g opacity="0.55">${r(x0 - 3, topY, x1 - x0, yb - topY, CYAN)}${r(x0 + 3, topY, x1 - x0, yb - topY, RED)}</g>`
      : ''

  const svg =
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 48" shape-rendering="crispEdges"${phase === 'done' ? ' opacity="0.5"' : ''}>` +
    glitch + m.draw(b, s, phase) + eyes + wear(m) + '</svg>'
  cache.set(id, svg)
  return svg
}
